WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), paid_at) AS days_since_paid_at FROM payments WHERE method = 'card' AND method IS NOT DISTINCT FROM 'paypal'), gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM base), islands AS (SELECT id, order_id, method, paid_at, status, days_since_paid_at, SUM(is_new_session) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT session_no, DATE_TRUNC('YEAR', paid_at) AS year_start, APPROX_PERCENTILE(session_no, 0.5) AS session_no_p50, SIZE(COLLECT_SET(method)) AS num_methods FROM islands GROUP BY GROUPING SETS ((session_no, DATE_TRUNC('YEAR', paid_at)), (session_no));
